using namespace opensim;using namespace scene;using namespace services;using framework::Uuid;
namespace {
void check(bool value,const char* text){if(!value)throw std::runtime_error(text);}
std::string path(const std::filesystem::path& p){auto u=p.u8string();return {reinterpret_cast<const char*>(u.data()),u.size()};}
std::vector<std::uint8_t> wire(const std::string& text){std::vector<std::uint8_t> data(text.begin(),text.end());data.push_back(0);return data;}
std::string field(const network::lludp::Packet& p,const char* block,const char* key){auto b=std::get<std::vector<std::uint8_t>>(p.block(block).at(key));return {b.begin(),std::find(b.begin(),b.end(),0)};}
void run(){
 auto directory=std::filesystem::temp_directory_path()/("opensim-region-asset-owner-"+Uuid::random().str());check(std::filesystem::create_directory(directory),"unique directory");struct Cleanup{std::filesystem::path path;~Cleanup(){if(path.parent_path()==std::filesystem::temp_directory_path()&&path.filename().string().starts_with("opensim-region-asset-owner-")){std::error_code error;std::filesystem::remove_all(path,error);}}}cleanup{directory};
 InventoryFolderStore folders(path(directory/"inventory.db"),true);InventoryService inventory(folders);StoredAssetService assets(std::make_shared<SqliteAssetStore>(path(directory/"assets.db"),true));auto owner=std::this_thread::get_id();int task_stores=0,agent_stores=0,script_checks=0;Uuid script;
 auto circuit=std::make_shared<framework::AgentCircuitData>();circuit->agent_id=Uuid::random();circuit->session_id=Uuid::random();circuit->secure_session_id=Uuid::random();circuit->circuit_code=42;circuit->caps_path="asset-owner";circuit->start_position={128,128,70};circuit->ip_address="127.0.0.1";circuit->first_name="Native";circuit->last_name="Owner";
 inventory.create_user_inventory(circuit->agent_id);InventoryItem note;note.id=Uuid::random();note.owner=circuit->agent_id;note.creator_id=circuit->agent_id.str();note.parent=inventory.root(circuit->agent_id)->id;note.name="Agent note";note.description="Description";note.asset_type=7;note.inventory_type=263;note.current_permissions=0x9e000;check(inventory.add_item(note),"real note");
 const std::string source="default\n{\n state_entry() { llSay(0, \"Script running\"); }\n}";auto initial=std::make_shared<framework::AssetBase>(Uuid("2074003b-8d5f-40e5-8b20-581c1c50aedb"),"Default script",10,circuit->agent_id.str());initial->description("");initial->data=std::make_shared<std::vector<std::uint8_t>>(source.begin(),source.end());check(assets.store(initial).has_value(),"actual default script asset");
 RegionPolicies policies;policies.log=[](const auto& text){std::cerr<<text<<'\n';};policies.access=[](auto,const auto&,auto&){return true;};policies.authorize=[](const auto&,auto&){return true;};policies.can_edit=[](auto agent,const auto& object){return agent==object.owner;};policies.inventory_service=&inventory;policies.store_asset=[&](auto asset){check(std::this_thread::get_id()==owner,"task store runs on owner");++task_stores;assets.store(std::move(asset));};policies.store_inventory_asset=[&](auto asset){check(std::this_thread::get_id()==owner,"agent store runs on owner");++agent_stores;return assets.store(std::move(asset));};policies.load_asset=[&](auto key){return assets.get_asset(key.str());};policies.can_edit_script=[&](auto,const auto&,const auto&){++script_checks;return true;};policies.new_script=[&](auto,auto,auto key){check(std::this_thread::get_id()==owner,"rez runs on owner");script=key;};
 NullPresenceStore presence_store;PresenceService presence(presence_store);GridRegion descriptor;descriptor.id=Uuid::random();descriptor.name="Asset owner";descriptor.external_host="127.0.0.1";descriptor.internal_endpoint=RegionEndpoint{"127.0.0.1",0};RegionRuntime runtime(descriptor,presence,std::move(policies));auto endpoint=runtime.start(std::make_shared<server::RegistryCapabilityListener>(server::CapabilityListenerInfo{false,19009,0,{}}));presence.login(circuit->agent_id.str(),circuit->session_id,circuit->secure_session_id);LoginTransferContext context;std::string reason;check(runtime.create_agent(nullptr,descriptor,circuit,128,context,reason),"real admission");
 std::atomic<std::uint32_t> sequence=0;std::mutex received_mutex;std::vector<network::lludp::Packet> received;network::UdpSocket* peer=nullptr;
 network::UdpSocket client({"127.0.0.1",0},[&](const auto& from,auto bytes){auto p=network::lludp::decode_datagram(bytes,65536,false);if(p.reliable){auto ack=network::lludp::make_packet("PacketAck");ack.reliable=false;ack.sequence=++sequence;auto b=network::lludp::make_block(ack.spec->blocks.at(0));b["ID"]=std::uint64_t(p.sequence);ack.blocks["Packets"].push_back(std::move(b));peer->send_to(from,network::lludp::encode_datagram(ack));}std::lock_guard lock(received_mutex);received.push_back(std::move(p));});peer=&client;client.start();
 auto make=[&](const char* name){auto p=network::lludp::make_packet(name);p.sequence=++sequence;if(p.blocks.contains("AgentData")){p.block("AgentData")["AgentID"]=circuit->agent_id;p.block("AgentData")["SessionID"]=circuit->session_id;}return p;};auto send=[&](const auto& p){client.send_to(endpoint,network::lludp::encode_datagram(p));};int stage=0;auto pump=[&](auto predicate){++stage;auto until=std::chrono::steady_clock::now()+std::chrono::seconds(4);while(!predicate()&&std::chrono::steady_clock::now()<until){runtime.poll();std::this_thread::sleep_for(std::chrono::milliseconds(1));}if(!predicate())throw std::runtime_error("region owner/UDP deadline stage "+std::to_string(stage));};
 auto use=make("UseCircuitCode");use.block("CircuitCode")["ID"]=circuit->agent_id;use.block("CircuitCode")["SessionID"]=circuit->session_id;use.block("CircuitCode")["Code"]=std::uint64_t(42);send(use);pump([&]{return runtime.viewers().agent(circuit->agent_id).has_value();});send(make("RegionHandshakeReply"));auto complete=make("CompleteAgentMovement");complete.block("AgentData")["CircuitCode"]=std::uint64_t(42);send(complete);pump([&]{auto actor=runtime.viewers().agent(circuit->agent_id);return actor&&actor->root;});
 auto update=[&](Uuid actor,Uuid item,Uuid object,const std::vector<std::uint8_t>& data){auto future=std::async(std::launch::async,[&runtime,actor,item,object,data]{return runtime.update_inventory_asset(actor,item,object,data);});try{pump([&]{return future.wait_for(std::chrono::milliseconds(0))==std::future_status::ready;});}catch(...){runtime.quiesce_script_updates();future.wait();throw;}return future.get();};
 std::vector<std::uint8_t> raw{'N',0,255,'Z'};auto asset=update(circuit->agent_id,note.id,{},raw);check(!asset.is_zero()&&agent_stores==1&&inventory.item(circuit->agent_id,note.id)->asset_id==asset&&*assets.get_data(asset.str())==raw,"queued real agent update persists exact raw data");check(inventory.item(circuit->agent_id,note.id)->inventory_type==263,"raw stored InventoryType retained");
 auto packet_seen=[&](const char* name,const char* text){std::lock_guard lock(received_mutex);return std::any_of(received.begin(),received.end(),[&](const auto& p){return p.spec->name==name&&field(p,"AlertData","Message")==text;});};pump([&]{return packet_seen("AlertMessage","Notecard updated");});auto deny=*inventory.item(circuit->agent_id,note.id);deny.current_permissions=0;inventory.update_item(deny);check(update(circuit->agent_id,note.id,{},raw).is_zero()&&agent_stores==1,"owner policy denial before store");pump([&]{return packet_seen("AgentAlertMessage","/Insufficient permissions to edit notecard");});check(update(Uuid::random(),note.id,{},raw).is_zero()&&agent_stores==1,"missing scene presence rejected");
 auto object=runtime.world().add(SceneObject::primitive(circuit->agent_id,runtime.viewers().agent(circuit->agent_id)->position));check(bool(object),"actual task part");auto rez=make("RezScript");auto& block=rez.block("InventoryBlock");block["FolderID"]=object->id;block["OwnerID"]=block["CreatorID"]=circuit->agent_id;block["BaseMask"]=block["OwnerMask"]=std::uint64_t(0x9e000);block["NextOwnerMask"]=std::uint64_t(0x82000);block["Type"]=block["InvType"]=std::int64_t(10);block["Name"]=wire("Live script");block["Description"]=wire("Default");send(rez);pump([&]{return !script.is_zero();});check(runtime.active_script_count()==1,"real native script instance");
 auto chats=[&]{std::set<std::uint32_t> ids;std::lock_guard lock(received_mutex);for(const auto& p:received)if(p.spec->name=="ChatFromSimulator"&&field(p,"ChatData","Message")=="Script running")ids.insert(p.sequence);return ids.size();};pump([&]{return chats()>0;});auto previous=chats();auto stores_before=task_stores;auto task_asset=update(circuit->agent_id,script,object->id,raw);check(!task_asset.is_zero()&&task_stores==stores_before+1&&*assets.get_data(task_asset.str())==raw&&runtime.active_script_count()==1&&script_checks==0,"generic task update does not invoke script editor policy or restart native VM");auto reset=make("ScriptReset");reset.block("Script")["ObjectID"]=object->id;reset.block("Script")["ItemID"]=script;send(reset);pump([&]{return chats()>previous;});check(runtime.active_script_count()==1,"reset still executes original compiled script after raw inventory asset edit");
 std::vector<std::future<bool>> pending;for(int n=0;n<16;++n)pending.push_back(std::async(std::launch::async,[&]{try{runtime.update_inventory_asset(circuit->agent_id,note.id,{},raw);return false;}catch(const std::exception&){return true;}}));runtime.quiesce_script_updates();for(auto& future:pending)check(future.wait_for(std::chrono::seconds(3))==std::future_status::ready&&future.get(),"quiesce cancels or rejects every queued asset update");bool rejected=false;try{runtime.update_inventory_asset(circuit->agent_id,note.id,{},raw);}catch(const std::exception&){rejected=true;}check(rejected,"post-quiesce rejection");client.stop();runtime.stop();
}
}
int main(){try{run();std::cout<<"PASS: actual UDP admission/root/alerts, scene-owner asset persistence, native VM retention/reset and16 shutdown cancellations\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
